function maxArea(height: number[]): number {
  let left = 0;
  let right = height.length - 1;
  let best = 0;

  while (left < right) {
    // Уровень воды ограничен более низкой стенкой
    const h = Math.min(height[left], height[right]);
    best = Math.max(best, h * (right - left));

    // Двигаем более низкую стенку: с ней любой более узкий
    // контейнер точно не лучше текущего
    if (height[left] < height[right]) {
      left++;
    } else {
      right--;
    }
  }

  return best;
}

// Время: O(n)
// Память: O(1)
